[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#step-1-define-context-interface-in-shell]

#### Step 1: Define Context Interface in Shell

```typescript
// shell/src/contexts/NotificationContext.ts
import { createContext, useContext } from 'react';

export interface Notification {
  id: string;
  title: string;
  message: string;
  timestamp: Date;
  read: boolean;
  severity: 'info' | 'warning' | 'error';
}

export interface NotificationContextValue {
  /** Unread notification count */
  count: number;

  /** Full notification list */
  items: Notification[];

  /** Mark notification as read */
  markAsRead: (id: string) => Promise<void>;

  /** Mark all notifications as read */
  markAllAsRead: () => Promise<void>;

  /** Add new notification (for testing/admin) */
  addNotification: (notification: Omit<Notification, 'id'>) => void;

  /** Clear all notifications */
  clearAll: () => Promise<void>;

  /** Refresh notifications from backend */
  refresh: () => Promise<void>;
}

export const NotificationContext = createContext<NotificationContextValue | undefined>(undefined);

/**

 * Hook to access notification context
 * Throws error if used outside NotificationProvider
 */
export function useNotifications(): NotificationContextValue {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within NotificationProvider');
  }
  return context;
}
```

