[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#step-2-implement-context-provider-in-shell]

#### Step 2: Implement Context Provider in Shell

```typescript
// shell/src/contexts/NotificationProvider.tsx
import { useState, useEffect, useCallback, useMemo, ReactNode } from 'react';
import { NotificationContext, Notification, NotificationContextValue } from './NotificationContext';

export function NotificationProvider({ children }: { children: ReactNode }) {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [loading, setLoading] = useState(true);

  // Calculate unread count
  const count = useMemo(() => {
    return notifications.filter((n) => !n.read).length;
  }, [notifications]);

  // Fetch notifications on mount
  useEffect(() => {
    fetchNotifications();
  }, []);

  async function fetchNotifications() {
    try {
      setLoading(true);
      const response = await fetch('/api/notifications', {
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to fetch notifications');
      }

      const data = await response.json();
      setNotifications(data.notifications);
    } catch (error) {
      console.error('[NotificationProvider] Failed to fetch notifications:', error);
      // Use cached notifications from localStorage
      const cached = localStorage.getItem('notifications');
      if (cached) {
        setNotifications(JSON.parse(cached));
      }
    } finally {
      setLoading(false);
    }
  }

  // Mark single notification as read
  const markAsRead = useCallback(async (id: string) => {
    try {
      // Optimistic update
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: true } : n))
      );

      // Update backend
      const response = await fetch(`/api/notifications/${id}/read`, {
        method: 'POST',
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to mark notification as read');
      }

      console.log(`[NotificationProvider] Marked notification ${id} as read`);
    } catch (error) {
      console.error('[NotificationProvider] Failed to mark as read:', error);

      // Rollback optimistic update
      setNotifications((prev) =>
        prev.map((n) => (n.id === id ? { ...n, read: false } : n))
      );

      throw error;
    }
  }, []);

  // Mark all notifications as read
  const markAllAsRead = useCallback(async () => {
    try {
      // Optimistic update
      setNotifications((prev) =>
        prev.map((n) => ({ ...n, read: true }))
      );

      // Update backend
      const response = await fetch('/api/notifications/read-all', {
        method: 'POST',
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to mark all as read');
      }

      console.log('[NotificationProvider] Marked all notifications as read');
    } catch (error) {
      console.error('[NotificationProvider] Failed to mark all as read:', error);

      // Rollback optimistic update
      await fetchNotifications();

      throw error;
    }
  }, []);

  // Add notification (for testing/real-time push)
  const addNotification = useCallback((notification: Omit<Notification, 'id'>) => {
    const newNotification: Notification = {
      ...notification,
      id: crypto.randomUUID(),
    };

    setNotifications((prev) => [newNotification, ...prev]);

    console.log('[NotificationProvider] Added notification:', newNotification);
  }, []);

  // Clear all notifications
  const clearAll = useCallback(async () => {
    try {
      // Optimistic update
      setNotifications([]);

      // Update backend
      const response = await fetch('/api/notifications', {
        method: 'DELETE',
        credentials: 'include',
      });

      if (!response.ok) {
        throw new Error('Failed to clear notifications');
      }

      console.log('[NotificationProvider] Cleared all notifications');
    } catch (error) {
      console.error('[NotificationProvider] Failed to clear notifications:', error);

      // Rollback optimistic update
      await fetchNotifications();

      throw error;
    }
  }, []);

  // Refresh notifications
  const refresh = useCallback(async () => {
    await fetchNotifications();
  }, []);

  // Persist to localStorage on change
  useEffect(() => {
    if (notifications.length > 0) {
      localStorage.setItem('notifications', JSON.stringify(notifications));
    }
  }, [notifications]);

  // Context value
  const value: NotificationContextValue = useMemo(
    () => ({
      count,
      items: notifications,
      markAsRead,
      markAllAsRead,
      addNotification,
      clearAll,
      refresh,
    }),
    [count, notifications, markAsRead, markAllAsRead, addNotification, clearAll, refresh]
  );

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
}
```

