[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#step-4-consume-context-in-modules]

#### Step 4: Consume Context in Modules

**Header Module (Consumer 1):**

```typescript
// header-mfe/src/components/NotificationBadge.tsx
import { useNotifications } from '@gainwell/shell/contexts';

export function NotificationBadge() {
  const { count } = useNotifications();

  return (
    <Badge count={count} onClick={() => navigate('/notifications')}>
      <BellIcon />
    </Badge>
  );
}
```

**Notifications Module (Consumer 2):**

```typescript
// notifications-mfe/src/pages/NotificationsList.tsx
import { useNotifications } from '@gainwell/shell/contexts';

export function NotificationsList() {
  const { items, markAsRead, markAllAsRead, refresh } = useNotifications();

  return (
    <div>
      <div className="header">
        <h1>Notifications ({items.length})</h1>
        <Button onClick={markAllAsRead}>Mark All as Read</Button>
        <Button onClick={refresh}>Refresh</Button>
      </div>

      <ul>
        {items.map((notification) => (
          <NotificationItem
            key={notification.id}
            notification={notification}
            onMarkAsRead={() => markAsRead(notification.id)}
          />
        ))}
      </ul>
    </div>
  );
}

function NotificationItem({
  notification,
  onMarkAsRead,
}: {
  notification: Notification;
  onMarkAsRead: () => void;
}) {
  return (
    <li className={notification.read ? 'read' : 'unread'}>
      <div className="content">
        <h3>{notification.title}</h3>
        <p>{notification.message}</p>
        <span>{formatDate(notification.timestamp)}</span>
      </div>

      {!notification.read && (
        <Button size="small" onClick={onMarkAsRead}>
          Mark as Read
        </Button>
      )}
    </li>
  );
}
```

**Flow:**
1. User clicks "Mark as Read" in Notifications panel
2. Notifications module calls `markAsRead(id)`
3. Shell's NotificationProvider updates context state
4. React triggers re-render of all components consuming NotificationContext
5. Header badge re-renders with new count
6. Notifications panel re-renders with updated item (marked as read)

