[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#step-5-testing-context-flows]

#### Step 5: Testing Context Flows

**Unit Testing Provider:**

```typescript
// shell/src/contexts/__tests__/NotificationProvider.test.tsx
import { renderHook, act } from '@testing-library/react-hooks';
import { NotificationProvider, useNotifications } from '../NotificationContext';

describe('NotificationProvider', () => {
  beforeEach(() => {
    // Mock fetch
    global.fetch = jest.fn();
  });

  it('should fetch notifications on mount', async () => {
    (global.fetch as jest.Mock).mockResolvedValueOnce({
      ok: true,
      json: async () => ({
        notifications: [
          { id: '1', title: 'Test', message: 'Test message', read: false, timestamp: new Date(), severity: 'info' },
        ],
      }),
    });

    const { result, waitForNextUpdate } = renderHook(() => useNotifications(), {
      wrapper: NotificationProvider,
    });

    await waitForNextUpdate();

    expect(result.current.count).toBe(1);
    expect(result.current.items).toHaveLength(1);
  });

  it('should mark notification as read and update count', async () => {
    (global.fetch as jest.Mock)
      .mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          notifications: [
            { id: '1', title: 'Test 1', read: false },
            { id: '2', title: 'Test 2', read: false },
          ],
        }),
      })
      .mockResolvedValueOnce({ ok: true });  // markAsRead API call

    const { result, waitForNextUpdate } = renderHook(() => useNotifications(), {
      wrapper: NotificationProvider,
    });

    await waitForNextUpdate();

    expect(result.current.count).toBe(2);

    // Mark notification as read
    await act(async () => {
      await result.current.markAsRead('1');
    });

    expect(result.current.count).toBe(1);
    expect(result.current.items.find((n) => n.id === '1')?.read).toBe(true);
  });
});
```

**Integration Testing Consumer:**

```typescript
// header-mfe/src/components/__tests__/NotificationBadge.test.tsx
