[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#after-shared-context-pattern]

#### After: Shared Context Pattern

**Shell Provides Context (After):**

```typescript
// shell/src/contexts/NotificationProvider.tsx (AFTER)
import { useState, useEffect, useCallback, useMemo } from 'react';

export function NotificationProvider({ children }) {
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    async function fetchNotifications() {
      const response = await fetch('/api/notifications');
      const data = await response.json();
      setNotifications(data);
    }

    fetchNotifications();

    // Fetch once on mount (no polling needed)
  }, []);

  const markAsRead = useCallback(async (id) => {
    // Optimistic update
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    );

    // Persist to backend
    await fetch(`/api/notifications/${id}/read`, { method: 'POST' });
  }, []);

  const value = useMemo(
    () => ({
      notifications,
      unreadCount: notifications.filter((n) => !n.read).length,
      markAsRead,
    }),
    [notifications, markAsRead]
  );

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
}
```

**Header Module (After):**

