[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#phi-protection-in-shared-context]

#### PHI Protection in Shared Context

**HIGH RISK PATTERN**: Shared Context is **high risk** for PHI exposure because:
1. Context is mutable (risk of accidental PHI injection)
2. Context visible to all consuming modules (difficult to control access)
3. Context may persist to localStorage (PHI persisted unencrypted)
4. Context updates trigger re-renders (PHI could leak to browser DevTools)

**Safe vs. Unsafe Context Data:**

✅ **Allowed in Shared Context:**

- Application UI state (theme, sidebar collapsed, modal visibility)
- Notification metadata (count, unread IDs)
- Shopping cart metadata (item count, cart ID)
- Wizard progress (step number, completed steps)
- Feature flags (enabled features)
- User preferences (language, timezone)

❌ **PROHIBITED in Shared Context:**

- Patient/member PHI (names, SSNs, dates of birth)
- Clinical data (diagnoses, procedures, medications)
- Claims details (amounts, provider information)
- Provider credentials (NPI, license numbers)
- Any mutable data subject to HIPAA Privacy Rule

**Safe Context Example:**

```typescript
// ✅ SAFE: Notification context with NO PHI
interface NotificationState {
  notifications: Array<{
    id: string;              // ✅ Notification ID
    type: 'success' | 'error' | 'warning' | 'info'; // ✅ UI state
    message: string;         // ✅ Generic message (no PHI)
    timestamp: string;       // ✅ Timestamp
    read: boolean;           // ✅ UI state
  }>;
  unreadCount: number;       // ✅ Count only
}

// Shell provides context
const NotificationContext = createContext<NotificationState>({notifications: [], unreadCount: 0});
```

**Unsafe Context Example (NEVER DO THIS):**

```typescript
// ❌ FORBIDDEN: Member PHI in shared context
interface MemberState {
  currentMember: {           // ❌ FORBIDDEN!
    memberId: string;
    firstName: string;       // ❌ PHI!
    lastName: string;        // ❌ PHI!
    dateOfBirth: string;     // ❌ PHI!
    ssn: string;             // ❌ PHI!
    eligibility: {           // ❌ PHI!
      planName: string;
      effectiveDate: string;
    };
  } | null;
}

// NEVER create this context!
const MemberContext = createContext<MemberState>({ currentMember: null });
```

**localStorage Security (NEVER store PHI):**

```typescript
// ❌ FORBIDDEN: Persisting PHI to localStorage
function NotificationProvider({ children }) {
  const [state, setState] = useState<NotificationState>(() => {
    const cached = localStorage.getItem('notifications');
    if (cached) {
      const parsed = JSON.parse(cached);
      // ❌ RISK: If notifications contain PHI, localStorage persists unencrypted
      return parsed;
    }
    return { notifications: [], unreadCount: 0 };
  });

  useEffect(() => {
    // ❌ FORBIDDEN: PHI persisted to browser storage
    localStorage.setItem('notifications', JSON.stringify(state));
  }, [state]);
}

// ✅ SAFE: Only persist non-PHI metadata
function NotificationProvider({ children }) {
  const [state, setState] = useState<NotificationState>(() => {
    const cached = localStorage.getItem('notificationPrefs');
    if (cached) {
      return JSON.parse(cached);
    }
    return { notificationsEnabled: true, soundEnabled: false };
  });

  useEffect(() => {
    // ✅ Safe: Only persist user preferences, not notification content
    localStorage.setItem('notificationPrefs', JSON.stringify({
      notificationsEnabled: state.notificationsEnabled,
      soundEnabled: state.soundEnabled
      // No PHI persisted
    }));
  }, [state]);
}
```

**Context Value Validation (PHI Detection):**

```typescript
// packages/mfe-context/src/validators/phiDetector.ts
const PHI_PATTERNS = [
  /firstName|lastName|name|fullName/i,
  /dateOfBirth|dob|birthDate/i,
  /ssn|socialSecurity/i,
  /diagnosis|procedure|medication/i,
  /medicalRecordNumber|mrn/i,
];

function detectPHIInObject(obj: unknown, path: string = ''): string[] {
  const violations: string[] = [];

  if (typeof obj !== 'object' || obj === null) {
    return violations;
  }

  for (const [key, value] of Object.entries(obj)) {
    const currentPath = path ? `${path}.${key}` : key;

    // Check if field name suggests PHI
    for (const pattern of PHI_PATTERNS) {
      if (pattern.test(key)) {
        violations.push(
          `Potential PHI field detected: ${currentPath}. ` +
          `Shared contexts MUST NOT contain PHI.`
        );
      }
    }

    // Recursively check nested objects
    if (typeof value === 'object' && value !== null) {
      violations.push(...detectPHIInObject(value, currentPath));
    }
  }

  return violations;
}

// Use in context provider
function NotificationProvider({ children }) {
  const [state, setState] = useState<NotificationState>(initialState);

  // Validate on every state update (development only)
  if (process.env.NODE_ENV === 'development') {
    useEffect(() => {
      const violations = detectPHIInObject(state, 'NotificationState');
      if (violations.length > 0) {
        console.error('PHI detected in shared context:', violations);
        throw new Error('PHI in shared context violates HIPAA compliance');
      }
    }, [state]);
  }

  return (
    <NotificationContext.Provider value={state}>
      {children}
    </NotificationContext.Provider>
  );
}
```

**Security Requirements:**
- **Type Safety**: All context values MUST use TypeScript interfaces with strict typing enabled (`strict: true` in tsconfig.json).
- **Immutability Enforcement**: Context MUST provide immutable state + mutation functions; prevent direct state mutation.
- **Error Boundaries**: Modules consuming context MUST wrap in Error Boundaries to prevent crashes from context errors.

