[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#security-implementation-for-shared-context]

#### Security Implementation for Shared Context

**Security Risk Assessment:**

| Risk | Severity | Mitigation |
|------|----------|------------|
| XSS via notification messages | **High** | DOMPurify sanitization before rendering |
| State corruption by malicious module | **High** | Immutability with Immer, type guards |
| localStorage quota DoS | Medium | Size limits, eviction policies |
| Context value tampering | **High** | Sealed objects, mutation functions only |
| Memory leak from large context | Medium | Size monitoring, cleanup policies |

**1. Immutable State Management with Immer:**

```typescript
// shell/src/contexts/NotificationContext.tsx
import { produce } from 'immer';
import { useState, useCallback } from 'react';
import DOMPurify from 'dompurify';
import Sentry from '@sentry/react';

interface Notification {
  id: string;
  type: 'success' | 'error' | 'warning' | 'info';
  message: string;
  timestamp: string;
  read: boolean;
}

interface NotificationState {
  notifications: Notification[];
  unreadCount: number;
}

export function NotificationProvider({ children }) {
  const [state, setState] = useState<NotificationState>({
    notifications: [],
    unreadCount: 0
  });

  // Mutation function: Add notification (immutable update)
  const addNotification = useCallback((notification: Omit<Notification, 'id' | 'timestamp' | 'read'>) => {
    // 1. Validate notification structure
    if (!notification.message || !notification.type) {
      throw new Error('Invalid notification: missing required fields');
    }

    // 2. Sanitize message to prevent XSS
    const sanitizedMessage = DOMPurify.sanitize(notification.message, {
      ALLOWED_TAGS: [],      // No HTML tags
      ALLOWED_ATTR: [],      // No attributes
      KEEP_CONTENT: true     // Keep text only
    });

    // 3. Immutable update with Immer (prevents accidental mutations)
    setState(produce(draft => {
      const newNotification: Notification = {
        id: crypto.randomUUID(),
        type: notification.type,
        message: sanitizedMessage,
        timestamp: new Date().toISOString(),
        read: false
      };

      draft.notifications.unshift(newNotification); // Add to front
      draft.unreadCount += 1;

      // 4. Enforce size limit (prevent memory exhaustion)
      if (draft.notifications.length > 100) {
        draft.notifications = draft.notifications.slice(0, 100);
      }

      // 5. Audit log (non-PHI metadata only)
      console.log('Notification added:', {
        id: newNotification.id,
        type: newNotification.type,
        timestamp: newNotification.timestamp
        // Don't log message content (could contain sensitive info)
      });
    }));
  }, []);

  // Mutation function: Mark as read
  const markAsRead = useCallback((id: string) => {
    setState(produce(draft => {
      const notification = draft.notifications.find(n => n.id === id);
      if (notification && !notification.read) {
        notification.read = true;
        draft.unreadCount = Math.max(0, draft.unreadCount - 1);
      }
    }));
  }, []);

  // Mutation function: Clear all
  const clearAll = useCallback(() => {
    setState({ notifications: [], unreadCount: 0 });
  }, []);

  // Context value (memoized to prevent unnecessary re-renders)
  const value = useMemo(() => ({
    ...state,
    addNotification,
    markAsRead,
    clearAll
  }), [state, addNotification, markAsRead, clearAll]);

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
}
```

**2. Type Guards and Validation:**

```typescript
// Type guard for notification validation
function isValidNotification(n: unknown): n is Notification {
  return (
    typeof n === 'object' &&
    n !== null &&
    'id' in n &&
    'type' in n &&
    'message' in n &&
    typeof (n as Notification).id === 'string' &&
    ['success', 'error', 'warning', 'info'].includes((n as Notification).type) &&
    typeof (n as Notification).message === 'string' &&
    (n as Notification).message.length <= 500 // Max message length
  );
}

// Validate when hydrating from localStorage
function NotificationProvider({ children }) {
  const [state, setState] = useState<NotificationState>(() => {
    try {
      const cached = localStorage.getItem('notifications');
      if (cached) {
        const parsed = JSON.parse(cached);

        // Validate each notification
        if (Array.isArray(parsed.notifications)) {
          const validNotifications = parsed.notifications.filter(isValidNotification);
          return {
            notifications: validNotifications,
            unreadCount: validNotifications.filter(n => !n.read).length
          };
        }
      }
    } catch (error) {
      // Log error but don't crash
      Sentry.captureException(error, {
        tags: { type: 'context_hydration_error' }
      });
    }

    return { notifications: [], unreadCount: 0 };
  });
}
```

**3. Context Size Monitoring:**

```typescript
// Monitor context size to prevent memory issues
function useContextSizeMonitoring(context: NotificationState) {
  useEffect(() => {
    const serialized = JSON.stringify(context);
    const sizeKB = new Blob([serialized]).size / 1024;

    if (sizeKB > 100) {
      console.warn(
        `NotificationContext size (${sizeKB.toFixed(2)}KB) exceeds ` +
        `recommended limit (100KB). Consider clearing old notifications.`
      );

      Sentry.captureMessage('Context size limit warning', {
        level: 'warning',
        extra: { sizeKB, notificationCount: context.notifications.length }
      });
    }
  }, [context]);
}
```

**4. Secure Context Consumer with Error Boundary:**

```typescript
// Module consuming context securely
function NotificationBadge() {
  const context = useContext(NotificationContext);

  // Validate context is provided
  if (!context) {
    console.warn('NotificationContext not provided—module running standalone');
    return <Badge count={0} />;
  }

  // Validate context structure (defensive programming)
  if (typeof context.unreadCount !== 'number') {
    console.error('Invalid NotificationContext: unreadCount not a number');
    Sentry.captureMessage('Invalid context structure', {
      level: 'error',
      extra: { contextKeys: Object.keys(context) }
    });
    return <Badge count={0} />;
  }

  return <Badge count={context.unreadCount} />;
}

// Wrap in Error Boundary
function NotificationBadgeWithErrorBoundary() {
  return (
    <ErrorBoundary
      fallback={<Badge count={0} />}
      onError={(error) => {
        Sentry.captureException(error, {
          tags: { component: 'NotificationBadge' }
        });
      }}
    >
      <NotificationBadge />
    </ErrorBoundary>
  );
}
```

**5. Prevent Direct State Mutation:**

```typescript
// Enforce read-only state at type level
export interface NotificationContextValue {
  readonly notifications: ReadonlyArray<Readonly<Notification>>;
  readonly unreadCount: number;
  readonly addNotification: (n: Omit<Notification, 'id' | 'timestamp' | 'read'>) => void;
  readonly markAsRead: (id: string) => void;
  readonly clearAll: () => void;
}

// Freeze context value in development
if (process.env.NODE_ENV === 'development') {
  Object.freeze(value);
  value.notifications.forEach(n => Object.freeze(n));
}
```

