[patterns/application/micro-frontend/PTN-APP-MFE-011-shared-context-pattern.md#phase-2-provider-implementation-weeks-2-3]

#### Phase 2: Provider Implementation (Weeks 2-3)

**2.1 Implement Context Provider**

```typescript
// shell/src/contexts/NotificationProvider.tsx
import React, { useState, useCallback, useMemo, useEffect, ReactNode } from 'react';
import { NotificationContext, Notification, NotificationContextValue } from './NotificationContext';

interface NotificationProviderProps {
  children: ReactNode;
}

export function NotificationProvider({ children }: NotificationProviderProps) {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  // Fetch notifications on mount
  useEffect(() => {
    async function fetchNotifications() {
      try {
        const response = await fetch('/api/notifications');
        const data = await response.json();
        setNotifications(data);
      } catch (err) {
        setError(err as Error);
      } finally {
        setIsLoading(false);
      }
    }

    fetchNotifications();
  }, []);

  // Mutation functions (memoized to prevent re-renders)
  const addNotification = useCallback((newNotification: Omit<Notification, 'id' | 'timestamp' | 'isRead'>) => {
    const notification: Notification = {
      ...newNotification,
      id: crypto.randomUUID(),
      timestamp: new Date().toISOString(),
      isRead: false,
    };

    setNotifications((prev) => [notification, ...prev]);

    // Persist to backend (fire-and-forget)
    fetch('/api/notifications', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(notification),
    }).catch(console.error);
  }, []);

  const markAsRead = useCallback((id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, isRead: true } : n))
    );

    // Persist to backend
    fetch(`/api/notifications/${id}/read`, { method: 'PUT' }).catch(console.error);
  }, []);

  const markAllAsRead = useCallback(() => {
    setNotifications((prev) => prev.map((n) => ({ ...n, isRead: true })));

    // Persist to backend
    fetch('/api/notifications/read-all', { method: 'PUT' }).catch(console.error);
  }, []);

  const removeNotification = useCallback((id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));

    // Persist to backend
    fetch(`/api/notifications/${id}`, { method: 'DELETE' }).catch(console.error);
  }, []);

  const refreshNotifications = useCallback(async () => {
    setIsLoading(true);
    try {
      const response = await fetch('/api/notifications');
      const data = await response.json();
      setNotifications(data);
      setError(null);
    } catch (err) {
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Memoize context value to prevent unnecessary re-renders
  const value = useMemo<NotificationContextValue>(() => ({
    notifications,
    unreadCount: notifications.filter((n) => !n.isRead).length,
    isLoading,
    error,
    addNotification,
    markAsRead,
    markAllAsRead,
    removeNotification,
    refreshNotifications,
  }), [notifications, isLoading, error, addNotification, markAsRead, markAllAsRead, removeNotification, refreshNotifications]);

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
}
```

**2.2 Integrate Provider into Shell**

