// eligibility-mfe/src/pages/DemographicsStep.tsx
import { useWizard } from '@gainwell/shell/contexts';

export function DemographicsStep() {
  const { nextStep } = useWizard();

  function handleSubmit(data: Demographics) {
    // Save data
    await saveDemographics(data);

    // Proceed to next step
    nextStep();
  }

  return <Form onSubmit={handleSubmit} />;
}
